class Solution:
    def maximumScore(self, nums: List[int], k: int) -> int:
        l = r = k                                # the window must contain index k
        low = best = nums[k]
        while l > 0 or r < len(nums) - 1:
            # expand towards the larger neighbour so the minimum drops as slowly as possible
            if l == 0 or (r < len(nums) - 1 and nums[r + 1] >= nums[l - 1]):
                r += 1
                low = min(low, nums[r])
            else:
                l -= 1
                low = min(low, nums[l])
            best = max(best, low * (r - l + 1))
        return best
